enum AnimState : uint8_t {
  ANIM_BOOT = 0,
  ANIM_COOLED = 1,
  ANIM_NEAR = 2,
  ANIM_COOLING = 3,
  ANIM_HOT = 4,
};
static const uint8_t ANIM_STATE_COUNT = 5;

static const uint16_t *const CLIP_BOOT[] = { FRAME_BOOT_0, FRAME_BOOT_1, FRAME_BOOT_2, FRAME_BOOT_3 };
static const uint16_t *const CLIP_COOLED[] = { FRAME_COOLED_0 };
static const uint16_t *const CLIP_NEAR[] = { FRAME_NEAR_0, FRAME_NEAR_1, FRAME_NEAR_2 };
static const uint16_t *const CLIP_COOLING[] = { FRAME_COOLING_0, FRAME_COOLING_1, FRAME_COOLING_2 };
static const uint16_t *const CLIP_HOT[] = { FRAME_HOT_0, FRAME_HOT_1 };

struct AnimClip {
  const uint16_t *const *frames;
  uint8_t count;
  uint16_t frame_ms;
};

static const AnimClip ANIM_CLIPS[ANIM_STATE_COUNT] = {
  { CLIP_BOOT, 4, 600 },
  { CLIP_COOLED, 1, 1000 },
  { CLIP_NEAR, 3, 300 },
  { CLIP_COOLING, 3, 220 },
  { CLIP_HOT, 2, 180 },
};

inline const AnimClip &animClip(AnimState s) {
  return ANIM_CLIPS[s < ANIM_STATE_COUNT ? s : 0];
}

inline const uint16_t *animFrame(AnimState s, uint8_t i) {
  const AnimClip &c = animClip(s);
  return c.frames[i % c.count];
}
